"""Score the eval bank. One shot per task, one headline number."""
import json

def load(path="evals/tasks.jsonl"):
    return [json.loads(line) for line in open(path)]

def score(agent):
    tasks = load()
    passed = 0
    for task in tasks:
        # Each task is executed exactly once. A task that succeeds one time
        # in three is indistinguishable here from one that always succeeds.
        if agent(task["prompt"]) == task["expect"]:
            passed += 1
    return {"pass_rate": passed / len(tasks)}

