"""Score the eval bank under repeated execution of the identical input."""
import json
import statistics

K = 8  # trials_per_task: the same prompt, re-executed unchanged

def load(path="evals/tasks.jsonl"):
    return [json.loads(line) for line in open(path)]

def score(agent):
    tasks = load()
    per_task = {}
    for task in tasks:
        hits = [agent(task["prompt"]) == task["expect"] for _ in range(K)]
        per_task[task["id"]] = hits
    # pass_hat_k: the task counts as passed only if every one of the K
    # identical executions passed. This is the deployment-relevant number.
    pass_hat_k = sum(all(h) for h in per_task.values()) / len(tasks)
    any_pass = sum(any(h) for h in per_task.values()) / len(tasks)
    per_task_stddev = {
        tid: statistics.pstdev([float(h) for h in hits])
        for tid, hits in per_task.items()
    }
    return {
        "pass_hat_k": pass_hat_k,
        "pass_at_1_upper_bound": any_pass,
        "k": K,
        "per_task_stddev": per_task_stddev,
    }
